"""Report fraudulent transaction tools."""

from __future__ import annotations

# The tool loader puts the agent root on sys.path while importing this module,
# so shared code under lib/ is importable from any tool location.
from lib.wallet_loader import load_wallet_data

from rasa.mantle.tools.decorator import ToolContext, tool
from rasa.mantle.tools.result import ToolResult

_wallet = load_wallet_data()


def _transactions_for_session(context: ToolContext) -> list:
    card_id = context.memory.get("card_disambiguation.selected_card_id")
    if card_id:
        return _wallet.transactions_for_card(str(card_id))
    if context.memory.get("recent_transactions"):
        return list(context.memory.get("recent_transactions"))
    return []


def _match_transaction_ids(
    transaction_ids: list[str], transactions: list
) -> tuple[list, list[str]]:
    by_id = {str(tx["id"]): tx for tx in transactions}
    matched: list = []
    unknown: list[str] = []
    for raw_id in transaction_ids:
        tid = str(raw_id).strip()
        if tid in by_id:
            if by_id[tid] not in matched:
                matched.append(by_id[tid])
        else:
            unknown.append(tid)
    return matched, unknown


@tool(
    description=(
        "Load recent charges for the card the customer already chose. "
        "Call only when that card does not have a charge list in context yet. "
        "Returns a customer-facing charge list and, for each charge, an internal id "
        "plus the line shown to the customer."
    )
)
async def fetch_recent_transactions(context: ToolContext = None) -> ToolResult:
    card_id = context.memory.get("card_disambiguation.selected_card_id")
    if not card_id:
        return ToolResult(
            llm_response={
                "transaction_available": False,
                "error": "No card selected yet.",
            }
        )

    transactions = _wallet.transactions_for_card(str(card_id))
    card = _wallet.get_card(str(card_id))
    card_label = (
        card["label"]
        if card
        else context.memory.get("card_disambiguation.selected_card_label")
    )
    payload = _wallet.transaction_tool_result(transactions, card_label=card_label)

    context.memory.set("transaction_available", payload["transaction_available"])
    context.memory.set("recent_transactions", transactions)
    context.memory.set("recent_transactions_text", payload["transactions_display_text"])
    context.memory.set("recent_transactions_card_id", card_id)
    context.memory.set("recent_transactions_card_label", card_label)
    context.memory.set("fraud_charges_presented", False)
    return ToolResult(
        llm_response={
            "card_id": card_id,
            "card_label": card_label,
            **payload,
        }
    )


@tool(description="Mark the loaded charges as presented for fraud filing.")
async def mark_fraud_charges_presented(context: ToolContext = None) -> ToolResult:
    transactions = _transactions_for_session(context)
    context.memory.set("fraud_charges_presented", True)
    return ToolResult(
        llm_response={
            "ok": True,
            "fraud_charges_presented": True,
            "transaction_count": len(transactions),
        }
    )


def _resolve_fraud_transaction_ids(
    transaction_ids: list[str], context: ToolContext
) -> tuple[list, list[str], dict | None]:
    if not transaction_ids:
        return (
            [],
            [],
            {
                "ok": False,
                "error": "no_transactions_specified",
                "hint": "Ask which charges are fraudulent, resolve to transaction ids, then call again.",
            },
        )

    card_id = context.memory.get("card_disambiguation.selected_card_id")
    list_card_id = context.memory.get("recent_transactions_card_id")
    if card_id and list_card_id and str(list_card_id) != str(card_id):
        return (
            [],
            [],
            {
                "ok": False,
                "error": "transaction_list_wrong_card",
                "hint": "Customer changed card — call fetch_recent_transactions for the current card first.",
            },
        )

    transactions = _transactions_for_session(context)
    if not transactions:
        return (
            [],
            [],
            {
                "ok": False,
                "error": "no_transactions_loaded",
                "hint": "Call fetch_recent_transactions first or complete Card Replace transaction review.",
            },
        )

    matched, unknown = _match_transaction_ids(transaction_ids, transactions)
    if unknown:
        valid = [str(tx["id"]) for tx in transactions]
        return (
            [],
            [],
            {
                "ok": False,
                "error": "unknown_transaction_ids",
                "unknown_ids": unknown,
                "valid_ids": valid,
                "hint": (
                    "Find the matching charge in recent_transactions, copy that object's "
                    "id field, and retry in the same turn."
                ),
            },
        )
    if not matched:
        return (
            [],
            [],
            {
                "ok": False,
                "error": "no_transactions_specified",
                "hint": "Pass at least one valid transaction id from the loaded list.",
                "count": 0,
            },
        )
    return matched, [], None


@tool(
    description=(
        "Record background replacement context the customer mentioned as an aside "
        "during fraud reporting (e.g. cracked chip, damaged card). Use only when "
        "they did not ask to start replacement yet. Do not set replacement_reason."
    )
)
async def note_replacement_hint(hint: str, context: ToolContext = None) -> ToolResult:
    normalized = (hint or "").strip().lower()
    if not normalized:
        return ToolResult(
            llm_response={
                "ok": False,
                "error": "empty_hint",
                "hint": "Pass a short hint such as damaged_chip.",
            }
        )
    context.memory.set("replacement_hint", normalized)
    return ToolResult(llm_response={"ok": True, "replacement_hint": normalized})


@tool(
    description=(
        "Record which charges the customer says are fraudulent. "
        "Each disputed charge must use the exact internal id from the loaded list — "
        "not a merchant name, date, display line, list position, or an id you invent "
        "(e.g. coffee_shop_05_04 is invalid). "
        "Find ids by matching the customer's words to a row in fetched transactions"
    )
)
async def select_fraudulent_transactions(
    pending_fraud_transaction_ids: list[str], context: ToolContext = None
) -> ToolResult:
    matched, _, error = _resolve_fraud_transaction_ids(
        pending_fraud_transaction_ids, context
    )
    if error:
        return ToolResult(llm_response=error)

    reported_lines = [tx["line"] for tx in matched]
    reported_ids = [tx["id"] for tx in matched]
    context.memory.set("pending_fraud_transaction_ids", reported_ids)
    context.memory.set(
        "fraud_report_summary_text",
        "\n".join(f"- {line}" for line in reported_lines),
    )
    context.memory.set("fraud_report_confirmed", None)
    return ToolResult(
        llm_response={
            "ok": True,
            "pending_fraud_transaction_ids": reported_ids,
            "reported_charges": reported_lines,
            "count": len(reported_ids),
        }
    )


@tool(
    description=(
        "Submit the fraud report after the customer confirmed the disputed-charge "
        "summary. Call only once those charges are already staged and the customer "
        "has agreed to file. Do not call before confirmation or if no charges were "
        "selected."
    )
)
async def file_fraud_report(context: ToolContext = None) -> ToolResult:
    pending_ids = context.memory.get("pending_fraud_transaction_ids") or []
    if not pending_ids:
        return ToolResult(
            llm_response={
                "filed": False,
                "ok": False,
                "error": "no_pending_fraud_transactions",
                "hint": "Call select_fraudulent_transactions first.",
            }
        )

    matched, _, error = _resolve_fraud_transaction_ids(list(pending_ids), context)
    if error:
        return ToolResult(llm_response={**error, "filed": False})

    reported_lines = [tx["line"] for tx in matched]
    reported_ids = [tx["id"] for tx in matched]
    context.memory.set("fraud_report_filed", True)
    context.memory.set("fraud_reported_charges", reported_lines)
    context.memory.set("fraud_reported_transaction_ids", reported_ids)
    context.memory.set("pending_fraud_transaction_ids", None)
    context.memory.set("fraud_report_summary_text", None)
    return ToolResult(
        llm_response={
            "filed": True,
            "ok": True,
            "reported_charges": reported_lines,
            "reported_transaction_ids": reported_ids,
            "count": len(reported_ids),
            "hint": (
                "Report filed. Skill ends automatically. If Card Replace was active it "
                "resumes; if standalone and the customer wants a replacement card, agent "
                "activates Card Replace next."
            ),
        }
    )
